CROSS JOIN (VALUES ('creek wattle'), ('silver wattle')) AS v(name)
WHERE p.genus = 'Acacia' AND p.species = 'rivalis'
ON CONFLICT (name, plant_id) DO NOTHING;

  genus, species, life_cycle, foliage, minheight, maxheight, minwidth, maxwidth,
  is_woody, is_tree, edible, thorns, sun, water, image_link, misc
) VALUES (
